// Pattern 1: Service with signals (no NgRx — good for most apps)
@Injectable({ providedIn: 'root' })
export class TodoStore {
  private todos = signal<Todo[]>([]);
  private filter = signal<'all' | 'active' | 'done'>('all');

  // Computed: derived state (like NgRx selectors)
  visibleTodos = computed(() => {
    const f = this.filter();
    const all = this.todos();
    if (f === 'active') return all.filter(t => !t.done);
    if (f === 'done') return all.filter(t => t.done);
    return all;
  });
  count = computed(() => this.todos().length);

  // Methods: mutations (like NgRx actions/reducers)
  add(text: string) { this.todos.update(ts => [...ts, { id: Date.now(), text, done: false }]); }
  toggle(id: number) { this.todos.update(ts => ts.map(t => t.id === id ? {...t, done: !t.done} : t)); }
  setFilter(f: typeof this.filter extends Signal<infer T> ? T : never) { this.filter.set(f); }
}

// Pattern 2: NgRx SignalStore (structured, scales better)
export const TodoStore = signalStore(
  { providedIn: 'root' },
  withState({ todos: [] as Todo[], filter: 'all' as const }),
  withComputed(({ todos, filter }) => ({
    visibleTodos: computed(() => todos().filter(/* ... */))
  })),
  withMethods((store) => ({
    addTodo: rxMethod<string>(pipe(
      switchMap(text => inject(TodoService).create(text)),
      tap(todo => patchState(store, { todos: [...store.todos(), todo] }))
    ))
  }))
);

// Pattern 3: Classic NgRx (when you need time-travel debug, Effects)
// actions.ts
const loadTodos = createAction('[Todo] Load');
const todosLoaded = createAction('[Todo] Loaded', props<{ todos: Todo[] }>());

// reducer.ts
const reducer = createReducer(initialState,
  on(todosLoaded, (state, { todos }) => ({ ...state, todos }))
);

// effect.ts
loadTodosEffect = createEffect(() =>
  this.actions$.pipe(
    ofType(loadTodos),
    switchMap(() => this.http.get<Todo[]>('/api/todos').pipe(
      map(todos => todosLoaded({ todos }))
    ))
  )
);
